// Layout primitive (Category B) — arrangement only, owns no look.
// Carve-out 5 (component-contract.md §6): references Sys layout scales directly,
// no Cmp token layer. A centred column that is a SPAN OF THE PAGE GRID, so its edges land on the
// grid's column lines and it follows whatever grid the brand sets. A px width scale would know nothing
// of the grid: in a brand whose grid caps at 1024px, a large container would be 1280.
import type { CSSProperties, ElementType, HTMLAttributes, Ref } from "react";
import { responsiveVars, type Responsive } from "./responsive";
import "./Container.css";

export interface ContainerProps extends Omit<HTMLAttributes<HTMLElement>, "className"> {
  /**
   * How many of the page grid's columns the column spans: 12 of 12 is the whole grid, 10 leaves one
   * column each side, 8 two, 6 three (a reading column). Centred, leave an EVEN number of columns over
   * so both edges stay on column lines. A plain number applies at every step and is clamped to the
   * columns there (8 is the whole grid on a 4-column phone); pass `{ small, medium, large }` to set
   * each step against its own column count. `full` removes the cap (the frame's whole width).
   *
   * @default 12
   */
  span?: Responsive<number> | "full";
  /**
   * `page` (default): the Container is the page frame and insets its content by the page-grid
   * margin. `none`: it sits inside a frame that already does (AppShell's main region, a LayoutGrid
   * item), so it only narrows to its span.
   *
   * @default "page"
   */
  padding?: "page" | "none";
  /**
   * Where a column narrower than its frame sits: centred, or on the frame's start edge (a form read
   * down one column under a page title). Either way its edges are on column lines.
   *
   * @default "center"
   */
  align?: "center" | "start";
  /** Render as a different element (e.g. "main", "section"). */
  as?: ElementType;
  className?: string;
  style?: CSSProperties;
  ref?: Ref<HTMLElement>;
}

export function Container({ span = 12, padding = "page", align = "center", as: Component = "div", className, style, ...props }: ContainerProps) {
  return (
    <Component
      {...props}
      data-full={span === "full" || undefined}
      data-padding={padding}
      data-align={align}
      className={className ? `sd-container ${className}` : "sd-container"}
      style={span === "full" ? style : { ...responsiveVars("span", span, String), ...style }}
    />
  );
}

/* Container.css — .sd-container
   Layout primitive: arrangement only. Carve-out 5 — references the Sys page grid directly (no Cmp
   layer). A column whose width is a span of the page grid, so its edges sit on column lines.
   `--sd-layout-span-<rung>` are local intermediates set inline (columns spanned at that rung), not
   tokens. Single class, no descendant combinators. */
.sd-container {
  --sd-layout-span-small: initial;
  --sd-layout-span-medium: initial;
  --sd-layout-span-large: initial;
  /* The inset this column keeps: the page margin when it is the page frame, none inside one. */
  --sd-layout-container-inset: var(--sd-grid-margin);
  /* The grid's content width here: what the frame allows, less the inset on both sides. */
  --sd-layout-container-grid: calc(min(100%, var(--sd-grid-max-width)) - 2 * var(--sd-layout-container-inset));
  /* Columns spanned at this rung, clamped to the rung's column count; unset, the whole grid. */
  --sd-layout-container-span: min(var(--sd-layout-span-small, var(--sd-grid-columns)), var(--sd-grid-columns));
  box-sizing: border-box;
  width: 100%;
  margin-inline: auto;
  padding-inline: var(--sd-layout-container-inset);
  max-width: calc(
    (var(--sd-layout-container-grid) + var(--sd-grid-gutter)) * var(--sd-layout-container-span) / var(--sd-grid-columns)
      - var(--sd-grid-gutter) + 2 * var(--sd-layout-container-inset)
  );
}

@media (min-width: 768px) {
  .sd-container {
    --sd-layout-container-span: min(
      var(--sd-layout-span-medium, var(--sd-layout-span-small, var(--sd-grid-columns))),
      var(--sd-grid-columns)
    );
  }
}

@media (min-width: 1024px) {
  .sd-container {
    --sd-layout-container-span: min(
      var(--sd-layout-span-large, var(--sd-layout-span-medium, var(--sd-layout-span-small, var(--sd-grid-columns)))),
      var(--sd-grid-columns)
    );
  }
}

.sd-container[data-padding="none"] {
  --sd-layout-container-inset: 0px;
}

/* Start-aligned on the GRID's start line, not the window's: past the grid's cap the frame is
   centred, so the column starts where the centred grid does. Inside a frame the gap is zero. */
.sd-container[data-align="start"] {
  margin-inline: max(0px, (100% - var(--sd-grid-max-width)) / 2) auto;
}

.sd-container[data-full] {
  max-width: none;
}
